const fs = require('node:fs')
const assert = require('node:assert/strict')
const notas=fs.readFileSync('app/api/integracoes/whatsapp/orcamento-notas/route.ts','utf8')
const atalho=fs.readFileSync('app/api/integracoes/whatsapp/conversa-direta/route.ts','utf8')
const pagina=fs.readFileSync('app/whatsapp/page.tsx','utf8')
const ui=fs.readFileSync('components/system/WhatsAppOrcamentoNotas.tsx','utf8')
const edge=fs.readFileSync('supabase/functions/whatsapp-gateway/index.ts','utf8')
assert.match(notas,/eq\('empresa_id', usuario\.empresa_id\)/)
assert.match(notas,/usuarioPodeAcaoServer/)
assert.match(notas,/atendimento_mensagens/)
assert.match(notas,/mensagens \|\| \[\]\)\.length === refs\.length && origens\.length === 1/)
assert.match(notas,/eq\('grupo_jid', conversa\.whatsapp_chat_jid\)/)
assert.match(notas,/origemStatus = !grupo \? 'nao_identificada'/)
assert.match(notas,/conversaId,/)
assert.match(ui,/Grupo de origem:/)
assert.match(ui,/origemStatus === 'outro_grupo'/)
assert.match(ui,/origemStatus === 'nao_identificada'/)
assert.match(ui,/Abrir este grupo no WhatsApp Atlas/)
assert.match(atalho,/autenticarTenant\(req\)/)
assert.match(atalho,/listarConversasAtendimento\(usuario, \{ modo: 'monitoramento' \}\)/)
assert.match(atalho,/c\.id === id && c\.whatsapp_chat_tipo === 'grupo'/)
assert.match(pagina,/\/api\/integracoes\/whatsapp\/conversa-direta\?conversaId=/)
assert.match(pagina,/setCanalFiltro\(canal\)/)
assert.match(pagina,/setAreaAtendimento\(solicitada\.whatsapp_chat_tipo === 'grupo' \? 'grupos' : 'individuais'\)/)
assert.match(pagina,/c\.id === conversaDiretaId && c\.whatsapp_chat_tipo === 'grupo'/)
assert.match(edge,/nomeGrupoOrcamento !== "orcamento \/ assistencia"\) return null/)
